INSERT INTO rules (id, code, brand_id, model_id, era_id, component_code, observation_key, check_json, polarity, severity, required, title_en, title_km, rationale, source_tier, citations_json, status, version) VALUES
 ('r_cbox_stamp_edge_c','CELINE-BOX-STAMP-EDGE-C','b_celine','m_celine_classic_box',NULL,'heat_stamp','stamp.edge_sharpness','{"type":"in","values":["blurred"]}','concern_indicator','major',0,'Logo stamp edges blurred','គែមអក្សរលើត្រាឡូហ្គោព្រិល','Blurred letterforms on the logo stamp. Judge only from a sharp macro photo; a blurry photo is not evidence.',4,'[{"type":"assistant_draft","note":"general construction check; attach a sourced reference before approval"}]','draft',1),
 ('r_cbox_stamp_edge_a','CELINE-BOX-STAMP-EDGE-A','b_celine','m_celine_classic_box',NULL,'heat_stamp','stamp.edge_sharpness','{"type":"in","values":["crisp"]}','authentic_indicator','minor',1,'Logo stamp edges crisp','គែមអក្សរលើត្រាឡូហ្គោច្បាស់','Weak on its own; must be compared with an approved reference of the same era.',4,'[{"type":"assistant_draft","note":"attach a sourced reference before approval"}]','draft',1),
 ('r_cbox_accent_era1_c','CELINE-BOX-ACCENT-ERA-C1','b_celine','m_celine_classic_box','e_celine_box_accent','heat_stamp','stamp.accent_e','{"type":"in","values":["no_accent"]}','concern_indicator','minor',0,'Logo without accent on an accented-era bag','ឡូហ្គោគ្មានសញ្ញា E លើកាបូប era មានសញ្ញា','Internal consistency: the stamp does not match the selected era. First check that the era was selected correctly.',4,'[{"type":"assistant_draft","note":"consistency check; era years still DRAFT"}]','draft',1),
 ('r_cbox_accent_era2_c','CELINE-BOX-ACCENT-ERA-C2','b_celine','m_celine_classic_box','e_celine_box_no_accent','heat_stamp','stamp.accent_e','{"type":"in","values":["accent_present"]}','concern_indicator','minor',0,'Accented logo on a no-accent-era bag','ឡូហ្គោមានសញ្ញា E លើកាបូប era គ្មានសញ្ញា','Internal consistency: the stamp does not match the selected era. First check that the era was selected correctly.',4,'[{"type":"assistant_draft","note":"consistency check; era years still DRAFT"}]','draft',1),
 ('r_cbox_stitch_reg_c','CELINE-BOX-STITCH-REG-C','b_celine','m_celine_classic_box',NULL,'stitching','stitch.regularity','{"type":"in","values":["uneven_wavy"]}','concern_indicator','major',0,'Flap stitching uneven / wavy','ថ្នេរគែម flap មិនស្មើ / រលក','Uneven spacing or angle along the curved flap edge. Ignore loose threads from wear.',4,'[{"type":"assistant_draft","note":"general construction check"}]','draft',1),
 ('r_cbox_stitch_reg_a','CELINE-BOX-STITCH-REG-A','b_celine','m_celine_classic_box',NULL,'stitching','stitch.regularity','{"type":"in","values":["even"]}','authentic_indicator','minor',1,'Flap stitching even','ថ្នេរគែម flap ស្មើ','Weak on its own; many counterfeits also stitch evenly.',4,'[{"type":"assistant_draft","note":"general construction check"}]','draft',1),
 ('r_cbox_hw_edge_c','CELINE-BOX-HW-EDGE-C','b_celine','m_celine_classic_box',NULL,'hardware','hardware.edge_finish','{"type":"in","values":["rough","solder_residue"]}','concern_indicator','major',0,'Clasp/buckle joints rough or with solder residue','ចំណុចភ្ជាប់ចាក់សោ/ក្បាលខ្សែគ្រើម ឬមានស្នាមប្រៃ','Look at hinge and plate joints, not at scratches or plating wear.',4,'[{"type":"assistant_draft","note":"general construction check"}]','draft',1),
 ('r_cbox_hw_edge_a','CELINE-BOX-HW-EDGE-A','b_celine','m_celine_classic_box',NULL,'hardware','hardware.edge_finish','{"type":"in","values":["clean"]}','authentic_indicator','minor',0,'Clasp/buckle joints clean','ចំណុចភ្ជាប់ចាក់សោ/ក្បាលខ្សែស្អាត',NULL,4,'[{"type":"assistant_draft","note":"general construction check"}]','draft',1),
 ('r_cbox_hw_engr_c','CELINE-BOX-HW-ENGR-C','b_celine','m_celine_classic_box',NULL,'hardware','hardware.engraving','{"type":"in","values":["fuzzy"]}','concern_indicator','major',0,'Hardware engraving fuzzy','ការឆ្លាក់លើផ្នែកដែកព្រិល','Only where an engraving exists; record nothing if the part is not engraved.',4,'[{"type":"assistant_draft","note":"general construction check"}]','draft',1),
 ('r_cbox_zip_solder_c','CELINE-BOX-ZIP-SOLDER-C','b_celine','m_celine_classic_box',NULL,'zipper','zipper.pull_finish','{"type":"in","values":["solder_residue"]}','concern_indicator','minor',0,'Solder residue on zipper slider/pull','មានស្នាមប្រៃលើក្បាល/ដៃទាញ zipper','Pitting and discolouration from age are excluded on purpose.',4,'[{"type":"assistant_draft","note":"general construction check"}]','draft',1);
